import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E5%8A%B3%E5%8A%A8%E5%90%88%E5%90%8C%E6%B3%95/%E5%8A%B3%E5%8A%A8%E5%90%88%E5%90%8C%E7%9A%84%E5%88%86%E7%B1%BB/","title":"劳动合同的分类 | notes","lang":"zh-CN","frontmatter":{"title":"劳动合同的分类","createTime":"2026/04/04 23:28:20","permalink":"/notes/劳动合同法/劳动合同的分类/","description":"用人单位不得扣押劳动者的身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物 符合一条即可签订 无固定期限劳动合同（出现法律规定的情形，也可终止和解除） 合同签完，一定要盖章 劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动合同在劳动合同文本上签字或者盖章生效","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"劳动合同的分类\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E5%8A%B3%E5%8A%A8%E5%90%88%E5%90%8C%E6%B3%95/%E5%8A%B3%E5%8A%A8%E5%90%88%E5%90%8C%E7%9A%84%E5%88%86%E7%B1%BB/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"劳动合同的分类"}],["meta",{"property":"og:description","content":"用人单位不得扣押劳动者的身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物 符合一条即可签订 无固定期限劳动合同（出现法律规定的情形，也可终止和解除） 合同签完，一定要盖章 劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动合同在劳动合同文本上签字或者盖章生效"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":2.13,"words":638},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/劳动合同法/劳动合同的分类.md","headers":[],"bulletin":true}`),a={name:`劳动合同的分类.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>用人单位不得扣押劳动者的<strong>身份证</strong>和<strong>其他证件</strong>，不得要求劳动者<strong>提供担保</strong>或者以其他名义向劳动者<strong>收取财物</strong></p><table><colgroup><col style="width:100%;"></colgroup><tbody><tr class="odd"><td>其他证件<br> 学历证明、技能证书、资格证等与劳动者就业相关的各类证件<br><br> 担保<br> 即指物的担保，也指人的担保<br><br> 其他名义向劳动者收取财物<br> 指与建立劳动关系有关的财物，如服装费、驾驶员风险费、保证金</td></tr></tbody></table><table><colgroup><col style="width:100%;"></colgroup><tbody><tr class="odd"><td>（1）以完成一定任务为期限的劳动合同 --建筑项目、软件项目 适用<br> （2）固定期限劳动合同 --连续订立二次后，续订时应该签订无固定期限劳动合同<br> （3）无固定期限劳动合同 --劳资双方不约定合同的终止时间</td></tr></tbody></table><p>符合一条即可签订 无固定期限劳动合同（出现法律规定的情形，也可终止和解除）</p><table><colgroup><col style="width:100%;"></colgroup><tbody><tr class="odd"><td>[1]双方协商一致，统一签订<br> [2]劳动者在用人单位连续工作满10年<br> [3]用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该单位连续工作满10年且距法定退休年龄不足10年<br> [4]连续订立二次固定期限劳动合同，且劳动者没有《劳动合同法》第39、40条第1、2项规定的情形，续订劳动合同的<br> [5]用人单位自用工之日起满一年不与劳动者订立书面合同的<br><br> 连续工作满10年：连续工作无中断（无间断，不是累积）<br> 用人单位初次实行劳动合同制度：事业单位初次实行劳动合同制度，以及事业单位专制为企业后初次与劳动者签订劳动合同的</td></tr></tbody></table><p>合同签完，一定要盖章</p><p>劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动合同在劳动合同文本上签字或者盖章生效</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};